{% import "fleetix/templates/print/fleetix_thermal.html" as tp with context %}
{% set visit = frappe.db.get_value("Customer Visit", doc.customer_visit, ["name", "odometer"], as_dict=True) if doc.customer_visit else None %}
{{ tp.style() }}
<div class="tp">
{{ tp.head(doc, _("Maintenance Invoice"), "Maintenance Invoice") }}
{{ tp.plate(doc.plate) }}
{{ tp.kv([
	(_("Customer"), "Customer", doc.customer_name),
	(_("Mobile No"), "Mobile", doc.mobile_no, 1),
	(_("Vehicle"), "Vehicle", doc.vehicle_description),
	(_("Date"), "Date", tp.dt(doc.posting_datetime) if doc.posting_datetime else None),
	(_("Odometer"), "Odometer km", tp.km(visit.odometer) if visit and visit.odometer else None),
]) }}
{{ tp.bar(_("Items"), "Items") }}
<table class="tp-grid">
<colgroup><col><col style="width:14mm"><col style="width:14mm"><col style="width:17mm"></colgroup>
<tr class="tp-h"><td>{{ _("Item", context="Print Line") }}<i>Item</i></td><td>{{ _("Qty", context="Print Line") }}<i>Qty</i></td><td>{{ _("Rate", context="Print Line") }}<i>Rate</i></td><td>{{ _("Amount", context="Print Line") }}<i>Amount</i></td></tr>
{% for r in doc.items %}<tr><td class="tp-s">{{ r.description }}</td><td class="tp-n">{{ "{:g}".format(r.qty or 0) }} {{ unit_label(r.uom) }}</td><td class="tp-n">{{ tp.money(r.rate) }}</td><td class="tp-n">{{ tp.money(r.amount) }}</td></tr>{% endfor %}
</table>
<table class="tp-sum" style="margin-top:2mm">
<tr><td><b>{{ _("Total before VAT") }}</b> <i>Subtotal</i></td><td class="tp-n">{{ tp.money(doc.net_total) }}</td></tr>
<tr><td><b>{{ _("VAT {0}%").format("{:g}".format(doc.vat_rate or 0)) }}</b> <i>VAT {{ "{:g}".format(doc.vat_rate or 0) }}%</i></td><td class="tp-n">{{ tp.money(doc.vat_amount) }}</td></tr>
<tr class="tp-grand"><td>{{ _("Total") }}<i>Total incl. VAT</i></td><td class="tp-n">{{ tp.money(doc.grand_total) }}</td></tr>
{% if doc.paid and doc.mode_of_payment %}<tr><td><b>{{ _(doc.mode_of_payment) }}</b> <i>{{ doc.mode_of_payment }}</i></td><td class="tp-n">{{ tp.money(doc.grand_total) }}</td></tr>{% endif %}
</table>
{{ tp.findings(frappe.get_all("Maintenance Finding", filters={"parent": visit.name, "parenttype": "Customer Visit"}, fields=["part", "reason", "note"], order_by="idx asc") if visit else []) }}
{{ tp.qr(doc) }}
{{ tp.foot(doc.company) }}
</div>
